#!/usr/bin/env python3
"""Bounded public research captures, with exact source metadata and compressed bytes."""
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import datetime,gzip,hashlib,json,requests,subprocess,tempfile
ROOT=Path(__file__).resolve().parent
URLS={'wsbtv-election2026': 'https://www.wsbtv.com/election2026/', 'wrdw-results': 'https://www.wrdw.com/politics/election-results/', 'accg-results': 'https://ers.accg.org/results.php', 'sos-calendar': 'https://sos.ga.gov/page/election-calendar-and-events', 'sos-calendar-pdf': 'https://sos.ga.gov/2026-elections-calendar-1', 'sos-voting-guide': 'https://sos.ga.gov/how-to-guide/how-guide-voting', 'nyt-elections': 'https://www.nytimes.com/section/politics/elections', 'fox5-results': 'https://www.fox5atlanta.com/election-results', 'wtoc-results': 'https://www.wtoc.com/politics/election-results/', 'wtoc-georgia': 'https://www.wtoc.com/georgia-election-results/', 'wabe-home': 'https://www.wabe.org/', 'npr-primary': 'https://apps.npr.org/primary-election-results-2026/states/GA.html', 'fox5-embed': 'https://media.foxtv.com/waga/elections/All.html', 'wtoc-ap-georgia': 'https://interactives.apelections.org/election-results/customers/layouts/organization-layouts/published/110246/32468.html', 'wtoc-ap-other': 'https://interactives.apelections.org/election-results/customers/layouts/organization-layouts/published/110246/32439.html', 'gpb-results': 'https://www.gpb.org/election/full-results', 'wabe-primary-counties': 'https://www.wabe.org/how-your-county-voted-in-georgias-biggest-primary-runoff-elections-on-tuesday/', 'wtvm-results': 'https://www.wtvm.com/politics/election-results/', 'wtvm-georgia': 'https://www.wtvm.com/georgia-election-results/', 'wtvm-may-night': 'https://www.wtvm.com/2026/05/19/election-night-2026-results-updates/', 'walb-home': 'https://www.walb.com/', 'walb-political': 'https://www.walb.com/news/political/', 'wmaz-home': 'https://www.13wmaz.com/', 'walb-results': 'https://www.walb.com/politics/election-results', 'wmaz-elections': 'https://www.13wmaz.com/elections', 'wmaz-counting': 'https://www.13wmaz.com/article/news/politics/elections/2026-midterm-elections-georgia-how-ballots-are-counted/85-e4f96f23-61b8-48bd-a612-c286dca00085', 'wmaz-early-turnout': 'https://www.13wmaz.com/article/news/politics/elections/georgia-early-voting-turnout-jumps-election-ga/93-1c13f2c8-d94e-4f8f-a8ac-55b068fe3435', 'sos-results-index': 'https://sos.ga.gov/page/georgia-election-results', 'sos-historical-index': 'https://sos.ga.gov/page/historical-elections-results', 'sos-results-app': 'https://results.sos.ga.gov/results/public/Georgia', 'sos-2024-qualified-writeins': 'https://sos.ga.gov/sites/default/files/forms/Write%20In%20Certification%20File%2011222024.pdf', 'sos-2022-qualified-writeins': 'https://sos.ga.gov/sites/default/files/2022-11/Certification%20of%20Write-In%20Candidates_November%208%20General%20Election.pdf', 'sos-2021-federal-runoff-zip': 'https://sos.ga.gov/sites/default/files/2026-04/january_5_2021_-_federal_runoff.zip', 'sos-2022-general-zip': 'https://sos.ga.gov/sites/default/files/2026-05/November%208%2C%202022%20-%20General-Special%20Election.zip', 'sos-2022-runoff-zip': 'https://sos.ga.gov/sites/default/files/2026-04/december_6_2022_-_general_election_runoff.zip', 'sos-2024-certification-news': 'https://sos.ga.gov/news/raffensperger-certifies-presidential-election-following-comprehensive-audits', 'sos-results-main-js': 'https://results.sos.ga.gov/results/public/main-WRC42TGG.js', 'sos-results-scripts-js': 'https://results.sos.ga.gov/results/public/scripts-TTWY4XDY.js', 'sos-results-service-chunk-js': 'https://results.sos.ga.gov/results/public/chunk-OJN5EB65.js', 'sos-results-jurisdiction': 'https://results.sos.ga.gov/results/public/api/jurisdictions/Georgia', 'sos-2024-general-api': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2024NovGen', 'sos-2021-federal-runoff-api': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2021JanFedRun', 'sos-2022-general-api': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2022NovGen', 'sos-2022-runoff-api': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2022DecGenRun', 'sos-2024-general-api-data': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2024NovGen/data', 'sos-2021-federal-runoff-api-data': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2021JanFedRun/data', 'sos-2022-general-api-data': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2022NovGen/data', 'sos-2022-runoff-api-data': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2022DecGenRun/data', 'sos-2024-general-api-data-selected': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2024NovGen/data/ballot-item/01000000-d884-2e72-6367-08dcda4b86b5', 'sos-2021-federal-runoff-api-data-selected': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2021JanFedRun/data/ballot-item/01000000-f6f4-3a08-4cda-08dd13a5434e', 'sos-2022-general-api-data-selected': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2022NovGen/data/ballot-item/01000000-39b2-c225-ad05-08dd132698c9', 'sos-2022-runoff-api-data-selected': 'https://results.sos.ga.gov/results/public/api/elections/Georgia/2022DecGenRun/data/ballot-item/01000000-f6f4-3a08-281a-08dd1325e294', 'sos-certified-writeins-2024-alias': 'https://sos.ga.gov/2024-certified-write-totals', 'nara-2024-index': 'https://www.archives.gov/electoral-college/2024', 'nara-2024-ascertainment': 'https://www.archives.gov/files/electoral-college/2024/ascertainment-georgia.pdf', 'fec-2024-presidential-original': 'https://www.fec.gov/documents/5644/2024presgeresults.pdf'}
def fetch(item):
 key,url=item;row={'id':key,'url':url,'retrieved_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  r=requests.get(url,timeout=35);path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(r.content,mtime=0))
  row.update(status=r.status_code,final_url=r.url,raw_sha256=hashlib.sha256(r.content).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(r.content),headers=dict(r.headers))
 except requests.exceptions.SSLError as e:
  row['requests_error']=str(e)
  with tempfile.TemporaryDirectory() as t:
   body=Path(t)/'body';hdr=Path(t)/'headers'
   c=subprocess.run(['curl','--silent','--show-error','--location','--max-time','35','--dump-header',str(hdr),'--output',str(body),'--write-out','%{http_code}\\n%{url_effective}',url],capture_output=True,text=True)
   row['transport']='system curl with default certificate verification'
   if c.returncode==0:
    code,final=c.stdout.split('\\n',1) if '\\n' in c.stdout else c.stdout.split('\n',1)
    raw=body.read_bytes();path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(raw,mtime=0))
    row.update(status=int(code),final_url=final,raw_sha256=hashlib.sha256(raw).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(raw),raw_headers=hdr.read_text())
   else:row['error']=c.stderr
 except requests.RequestException as e:row['error']=str(e)
 return row
if __name__=='__main__':
 rows=list(ThreadPoolExecutor(max_workers=4).map(fetch,URLS.items()));(ROOT/'manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
 for r in rows:print(r['id'],r.get('status',r.get('error')))
